// src/data/sentenceMeanings.ts
// ─────────────────────────────────────────────────────────────────────────────
// 중급·고급 받아쓰기 문장(sentences.ts)의 의미(번역) — 정답 확인 후에만 노출.
//   · 키는 'int_<id>' / 'adv_<id>' (DictationSentence.level + id 로 조합, sentenceKey 참고).
//   · 값은 { en, es, ja } 3개 언어. 한국어(ko) 사용자는 표시하지 않는다.
//   · 값이 비어 있으면(아직 미번역) 화면에 아무것도 표시되지 않는다.
//   · 각 줄 끝 주석은 번역 대상 한국어 원문(참고용).
//   · TODO(번역): 아래 M() 안에 en, es, ja 순서로 채우면 즉시 화면에 반영된다.
//       예) 'int_1': M('Could you bring me a menu?', '¿Me traería el menú?', 'メニューを持ってきていただけますか？'),
// ─────────────────────────────────────────────────────────────────────────────

import type { Lang } from '@/lib/i18n'
import type { DictationSentence } from './sentences'
import { type Meaning, meaningText } from './wordMeanings'

const M = (en = '', es = '', ja = ''): Meaning => ({ en, es, ja })

/** DictationSentence → SENTENCE_MEANINGS 조회 키. */
export function sentenceKey(s: DictationSentence): string {
  return (s.level === 'advanced' ? 'adv' : 'int') + '_' + s.id
}

/** 한 문장의 의미를 바로 얻는 편의 함수. */
export function sentenceMeaning(s: DictationSentence, lang: Lang): string {
  return meaningText(SENTENCE_MEANINGS[sentenceKey(s)], lang)
}

